package com.fitbite.controller; import com.fitbite.dto.*; import com.fitbite.dto.PreferenceDtos.*; import com.fitbite.service.PreferenceService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profile") public class PreferenceController{private final PreferenceService service;public PreferenceController(PreferenceService service){this.service=service;}@GetMapping public ApiResponse<ProfileResponse> profile(){return ApiResponse.ok("Profile fetched",service.profile());}@PutMapping public ApiResponse<ProfileResponse> update(@Valid @RequestBody PreferenceRequest r){return ApiResponse.ok("Preferences updated",service.update(r));}}
